window.docContents[229].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___16___-Problems/Section-5___16___-Problems-on-Young-diagrams-and-branching-rules/#Chapter5___Introduction_5___16___heading-1":{"contents":"In the following problems, we do not make a distinction between Young diagrams and partitions.\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.16. Problems\tSection 5.16: Problems on Young diagrams and branching rules","header":"5.16. Problems","id":"/5___-Representations-of-finite-groups___-Further-results/5___16___-Problems/Section-5___16___-Problems-on-Young-diagrams-and-branching-rules/#Chapter5___Introduction_5___16___heading-1"},"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Section-8___2___-Tor-and-Ext-functors/#Chapter8___Introduction_8___2___heading-1":{"contents":"Let A be a unital ring. As we have mentioned in Example 7.9.6, the functors M \\otimes_A ? and \\operatorname{Hom}_A(M, ?) (where M is a right, respectively\nleft, A-module) on the category of left A-modules are, in general, not exact (they are only exact on one side). The job of the functors \\mathrm{Tor}_i^A(M, ?) and \\mathrm{Ext}^i_A(M, ?) is to quantify the extent to which the functors M \\otimes_A ? and \\mathrm{Hom}_A(M, ?) fail to be exact. Namely, these functors are defined as follows.\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.2. Tor and Ext functors\tSection 8.2: Tor and Ext functors","header":"8.2. Tor and Ext functors","id":"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Section-8___2___-Tor-and-Ext-functors/#Chapter8___Introduction_8___2___heading-1"}});
